602: 
603:   const AudioContext = window.AudioContext || window.webkitAudioContext;
604:   if (!AudioContext) return;
605: 
606:   ambientAudioCtx = new AudioContext();
607: 
608:   // Create Master Gain Node
609:   ambientGainNode = ambientAudioCtx.createGain();
610:   ambientGainNode.gain.setValueAtTime(0, ambientAudioCtx.currentTime);
611:   ambientGainNode.connect(ambientAudioCtx.destination);
