614: /**
615:  * Generate a 5-second seamless stereo Brown Noise AudioBuffer
616:  */
617: function createBrownNoiseBuffer() {
618:   const sampleRate = ambientAudioCtx.sampleRate;
619:   const bufferSize = sampleRate * 5;
620:   const buffer = ambientAudioCtx.createBuffer(2, bufferSize, sampleRate);
621: 
622:   for (let channel = 0; channel < 2; channel++) {
623:     const data = buffer.getChannelData(channel);
624:     let lastOut = 0.0;
625:     for (let i = 0; i < bufferSize; i++) {
626:       const white = Math.random() * 2 - 1;
627:       lastOut = (lastOut + (0.02 * white)) / 1.02;
628:       data[i] = lastOut * 2.8;
629:     }
630:   }
631:   return buffer;
632: }
