643: /**
644:  * Start ambient audio with smooth fade-in
645:  */
646: function startAmbient(auto = false) {
647:   initAmbientAudio();
648:   if (!ambientAudioCtx) return;
649: 
650:   if (ambientAudioCtx.state === 'suspended') {
651:     ambientAudioCtx.resume();
652:   }
653: 
654:   autoStartedByTimer = auto;
655: 
656:   if (isAmbientPlaying) {
657:     ambientGainNode.gain.setTargetAtTime(getTargetGain(), ambientAudioCtx.currentTime, 0.2);
658:     return;
659:   }
660: 
661:   // Create and connect noise source
662:   const noiseBuffer = createBrownNoiseBuffer();
663:   ambientSourceNode = ambientAudioCtx.createBufferSource();
664:   ambientSourceNode.buffer = noiseBuffer;
665:   ambientSourceNode.loop = true;
666: 
667:   // Gentle low-pass filter to make it deeply warm and relaxing (~360Hz)
668:   const lowpass = ambientAudioCtx.createBiquadFilter();
669:   lowpass.type = 'lowpass';
670:   lowpass.frequency.setValueAtTime(360, ambientAudioCtx.currentTime);
671: 
672:   ambientSourceNode.connect(lowpass);
673:   lowpass.connect(ambientGainNode);
674: 
675:   // Smooth fade-in
676:   ambientGainNode.gain.setValueAtTime(0.0001, ambientAudioCtx.currentTime);
677:   ambientGainNode.gain.exponentialRampToValueAtTime(Math.max(0.0001, getTargetGain()), ambientAudioCtx.currentTime + 0.6);
